    text {
      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
      font-size: 7.5px;
      fill: currentColor;
    }
    .muted { opacity: 0.55; }
    .faint { opacity: 0.35; }
    .scope { animation: scope 8s ease-in-out infinite; }
    .all { opacity: 0; animation: all 8s ease-in-out infinite; }
    .cursor { animation: blink 1s steps(1) infinite; }
    @keyframes scope {
      0%, 38% { opacity: 1; }
      46%, 92% { opacity: 0; }
      100% { opacity: 1; }
    }
    @keyframes all {
      0%, 38% { opacity: 0; transform: translateY(3px); }
      50%, 92% { opacity: 1; transform: translateY(0); }
      100% { opacity: 0; transform: translateY(3px); }
    }
    @keyframes blink {
      0%, 49% { opacity: 1; }
      50%, 100% { opacity: 0; }
    }
    @media (prefers-reduced-motion: reduce) {
      .scope, .all, .cursor { animation: none; }
      .all { opacity: 0; }
      .cursor { opacity: 1; }
    }
  </style>
  <rect x="1" y="1" width="238" height="70" rx="5" fill="none" stroke="currentColor" stroke-opacity="0.25"/>

  <g class="scope">
    <text x="12" y="20">$ opencode session list</text>
    <rect class="cursor" x="118" y="14" width="4" height="8" fill="currentColor"/>
