    const server = net.createServer();
    server.unref();
    server.on("error", reject);
    server.listen(0, "127.0.0.1", () => {
      const address = server.address();
      const port = typeof address === "object" && address ? address.port : 0;
      server.close(() => (port ? resolve(port) : reject(new Error("no free port"))));
    });
  });
}

/** A real on-disk install tree: this is what summarizeGatewayServiceLayout walks. */
async function writeInstallTree(root: string, buildId: string, version: string): Promise<void> {
  await fs.mkdir(path.join(root, "dist"), { recursive: true });
  await fs.writeFile(
    path.join(root, "package.json"),
    `${JSON.stringify({ name: "openclaw", version }, null, 2)}\n`,
  );
  await fs.writeFile(
    path.join(root, "dist", "build-info.json"),
    `${JSON.stringify({ buildId, builtAt: new Date().toISOString() }, null, 2)}\n`,
  );
  await fs.writeFile(path.join(root, "dist", "entry.mjs"), "// proof install entrypoint\n");
}

type CapturedTerminal = {
  lines: string[];
  out: {
    printInfo: (name: string, value: string) => void;
    printWarning: (message: string) => void;
    infoText: (value: string) => string;
    spacer: () => void;
  };
};

function captureTerminal(): CapturedTerminal {
  const lines: string[] = [];
  return {
    lines,
    out: {
      printInfo: (name, value) => lines.push(`${name} ${value}`),
      printWarning: (message) => lines.push(message),
      infoText: (value) => value,
      spacer: () => {},
    },
  };
}

