/**
 * Tees every byte the process would print into a buffer. The Gateway's
 * subsystem logger ends up on stdout/stderr, so this is the cheapest place to
 * read what an operator watching startup sees without replacing the logger.
 */
function captureOutput(): { stop: () => string } {
  let buffer = "";
  const originals = {
    stdout: process.stdout.write.bind(process.stdout),
    stderr: process.stderr.write.bind(process.stderr),
  };
  const record = (chunk: unknown): void => {
    buffer += typeof chunk === "string" ? chunk : String(chunk);
  };
  process.stdout.write = ((chunk: unknown, ...rest: unknown[]) => {
    record(chunk);
    return (originals.stdout as (...args: unknown[]) => boolean)(chunk, ...rest);
  }) as typeof process.stdout.write;
  process.stderr.write = ((chunk: unknown, ...rest: unknown[]) => {
    record(chunk);
    return (originals.stderr as (...args: unknown[]) => boolean)(chunk, ...rest);
  }) as typeof process.stderr.write;
  return {
    stop: () => {
      process.stdout.write = originals.stdout as typeof process.stdout.write;
      process.stderr.write = originals.stderr as typeof process.stderr.write;
      return buffer;
    },
  };
}

