import assert from "node:assert/strict";
import { execFileSync, spawnSync } from "node:child_process";
import { copyFileSync, mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import path from "node:path";
import { pathToFileURL } from "node:url";

const REPO = process.cwd();
const MODULES_DIR = path.dirname(
  path.dirname(createRequire(import.meta.url).resolve("tsx/package.json")),
);
const COPIED = [
  "scripts/run-vitest.mjs",
  "scripts/tsx.mjs",
  "scripts/windows-cmd-helpers.mjs",
  "scripts/lib/tsx-cli-shim.mjs",
  "scripts/lib/local-check-runtime.mts",
  "scripts/lib/tooling-dependencies.mjs",
  "scripts/lib/managed-child-process.mts",
  "scripts/lib/managed-cleanup-handoff.mts",
  "scripts/lib/vitest-resource-ownership.mts",
  "scripts/lib/vitest-worker-descriptor.mts",
  "scripts/lib/windows-taskkill.mjs",
];

type Scenario = {
  label: string;
  childExitCode: number;
  disposeBody: string;
  /** When set, the wrapper and shim are taken from this git revision. */
  revision?: string;
};

function run({ label, childExitCode, disposeBody, revision }: Scenario) {
  const root = mkdtempSync(path.join(tmpdir(), "proof-197486-"));
  const checkout = path.join(root, "checkout");
  mkdirSync(path.join(checkout, ".git"), { recursive: true });
  for (const file of COPIED) {
    const target = path.join(checkout, file);
    mkdirSync(path.dirname(target), { recursive: true });
    copyFileSync(path.join(REPO, file), target);
  }
  writeFileSync(path.join(checkout, "pnpm-lock.yaml"), "lockfileVersion: '9.0'\n");
  if (revision) {
    for (const file of ["scripts/run-vitest.mjs", "scripts/lib/tsx-cli-shim.mjs"]) {
      writeFileSync(
        path.join(checkout, file),
        execFileSync("git", ["show", `${revision}:${file}`], { cwd: REPO, encoding: "utf8" }),
      );
    }
  }

  const workerDirectory = path.join(checkout, "worker");
  mkdirSync(workerDirectory, { recursive: true });
  writeFileSync(
    path.join(checkout, "scripts/run-vitest-child.mts"),
    `process.exitCode = ${childExitCode};\n`,
  );
  writeFileSync(
    path.join(checkout, "scripts/lib/vitest-worker-bootstrap.mts"),
    'import { pathToFileURL } from "node:url";\nawait import(pathToFileURL(process.argv[3]).href);\n',
  );
  writeFileSync(
    path.join(checkout, "scripts/lib/vitest-worker-run.mts"),
    `export function createVitestWorkerRun() {
  return {
    descriptor: { directory: ${JSON.stringify(workerDirectory)} },
    withBorrower: (borrow) => borrow(() => {}),
    async dispose() {
      ${disposeBody}
    },
  };
}
`,
  );
  const installer = path.join(checkout, "scripts/install-worker-descriptor.mjs");
  writeFileSync(
    installer,
    `import { installVitestWorkerDescriptor } from "./lib/vitest-worker-descriptor.mts";
installVitestWorkerDescriptor({ directory: ${JSON.stringify(workerDirectory)} });
`,
  );

  const env = { ...process.env, PNPM_CONFIG_MODULES_DIR: MODULES_DIR };
  delete env.NODE_OPTIONS;
  const result = spawnSync(
    process.execPath,
    ["--import", pathToFileURL(installer).href, path.join(checkout, "scripts/run-vitest.mjs")],
    { cwd: REPO, encoding: "utf8", env },
  );
  const markers = result.stderr
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.startsWith("[test] "));
  console.log(
    `\n--- ${label}\nstatus: ${result.status}\nmarkers: ${JSON.stringify(markers)}\nstderr (last 3 lines):\n${result.stderr.trim().split("\n").slice(-3).join("\n")}`,
  );
  return { status: result.status, markers, stderr: result.stderr };
}

const clean = run({ label: "passing child + clean disposal", childExitCode: 0, disposeBody: "" });
assert.deepEqual(clean.markers, ["[test] EXIT 0"], "a clean run must end with exactly one EXIT 0");
assert.equal(clean.status, 0, "a clean run must exit 0");

const cleanupFailed = run({
  label: "passing child + failing cleanup release",
  childExitCode: 0,
  disposeBody: 'throw new Error("cleanup release failed");',
});
assert.ok(
  !cleanupFailed.stderr.includes("[test] EXIT 0"),
  "a run that ends non-zero must never print EXIT 0",
);
assert.deepEqual(
  cleanupFailed.markers,
  ["[test] EXIT 2", "[test] FAILED (exit 2)"],
  "a cleanup-release failure must be marked as the failure it is",
);
assert.equal(cleanupFailed.status, 2, "a cleanup-release failure must exit non-zero");
assert.ok(
  cleanupFailed.stderr.includes("cleanup release failed"),
  "the disposal error must stay visible",
);

const childFailed = run({
  label: "failing child + clean disposal",
  childExitCode: 2,
  disposeBody: "",
});
assert.deepEqual(
  childFailed.markers,
  ["[test] EXIT 2", "[test] FAILED (exit 2)"],
  "a failing child must still be marked once",
);
assert.equal(childFailed.status, 2, "a failing child must exit non-zero");

const before = run({
  label: "BEFORE (wrapper + shim from HEAD): passing child + failing cleanup release",
  childExitCode: 0,
  disposeBody: 'throw new Error("cleanup release failed");',
  revision: "HEAD",
});
assert.ok(
  before.markers.includes("[test] EXIT 0"),
  "the pre-fix revision is expected to print the false EXIT 0",
);
assert.notEqual(before.status, 0, "the pre-fix revision still ends the run non-zero");

console.log("\nAll runtime assertions passed.");
