<summary>Full proof script</summary>

```ts
/**
 * Real-behavior proof for openclaw/openclaw#197119:
 * "cancel in-flight MCP listener work when shutdown starts".
 *
 * REAL in this script: the MCP loopback HTTP listener (`ensureMcpLoopbackServer` /
 * `closeMcpLoopbackServer`), HTTP requests over a real socket, the grant store and run
 * admission, the plugin loader (a fixture plugin loaded from disk through
 * `plugins.load.paths`), tool resolution, and the tool callback's execution with the
 * signal the listener hands it.
 *
 * FIXTURE: the plugin's one tool, `shutdown_probe_wait`. It records when it starts,
 * waits for the signal it was given to abort, then does 200 ms of async cleanup and
 * records when that finishes. It never returns on its own, and the HTTP client stays
 * connected, so only listener-side cancellation can end it.
 *
 * Scenarios:
 *  1. A call that finishes before shutdown is unaffected.
 *  2. Shutdown begins while the callback is still executing: its signal aborts, its
 *     cleanup completes, and close() resolves instead of waiting on the open response.
 *
 * Run: node --import ./scripts/tsx.mjs scripts/proof-197119-mcp-shutdown-cancel.ts
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const dir = fs.mkdtempSync(path.join(os.tmpdir(), "proof-197119-"));
const stateDir = path.join(dir, "state");
const pluginDir = path.join(dir, "shutdown-probe");
const marks = path.join(dir, "marks.log");
process.env.OPENCLAW_STATE_DIR = stateDir;
process.env.OPENCLAW_CONFIG_PATH = path.join(dir, "openclaw.json");
for (const d of [stateDir, pluginDir, path.join(dir, "ws")]) {
  fs.mkdirSync(d, { recursive: true });
}
fs.writeFileSync(
  path.join(pluginDir, "openclaw.plugin.json"),
  JSON.stringify({
    id: "shutdown-probe",
    name: "Shutdown Probe",
    description: "Proof fixture: a tool that runs until its execute signal aborts",
    configSchema: { type: "object", additionalProperties: false, properties: {} },
    contracts: { tools: ["shutdown_probe_wait", "shutdown_probe_quick"] },
  }),
);
fs.writeFileSync(
  path.join(pluginDir, "index.cjs"),
  `const fs = require("node:fs");
const mark = (name) => fs.appendFileSync(${JSON.stringify(marks)}, name + " " + Date.now() + "\\n");
module.exports = {
  id: "shutdown-probe",
  name: "Shutdown Probe",
  register(api) {
    api.registerTool({
      name: "shutdown_probe_quick",
      description: "Returns immediately",
      parameters: { type: "object", properties: {}, additionalProperties: false },
      async execute() {
        return { content: [{ type: "text", text: "quick-ok" }] };
      },
    });
    api.registerTool({
      name: "shutdown_probe_wait",
      description: "Runs until its execute signal aborts, then cleans up",
      parameters: { type: "object", properties: {}, additionalProperties: false },
      async execute(_id, _params, signal) {
        mark("callback-started");
        await new Promise((resolve) => {
          if (signal.aborted) resolve();
          else signal.addEventListener("abort", resolve, { once: true });
        });
        mark("callback-signal-aborted");
        await new Promise((resolve) => setTimeout(resolve, 200));
        mark("callback-cleanup-done");
        return { content: [{ type: "text", text: "ended-by-cancellation" }] };
      },
    });
  },
};
`,
);
const cfg = {
  session: { mainKey: "main" },
  agents: { defaults: { workspace: path.join(dir, "ws") } },
  plugins: {
    enabled: true,
    load: { paths: [pluginDir] },
    entries: { "shutdown-probe": { enabled: true } },
  },
  tools: { alsoAllow: ["shutdown_probe_wait", "shutdown_probe_quick"] },
};
fs.writeFileSync(process.env.OPENCLAW_CONFIG_PATH, JSON.stringify(cfg));

const { setRuntimeConfigSnapshot } = await import("../src/config/runtime-snapshot.js");
setRuntimeConfigSnapshot(cfg as never);
const { ensureMcpLoopbackServer, closeMcpLoopbackServer } =
  await import("../src/gateway/mcp-http.js");
const { getActiveMcpLoopbackRuntime } = await import("../src/gateway/mcp-http.loopback-runtime.js");
const store = await import("../src/gateway/mcp-grant-store.js");
const admissionApi = await import("../src/agents/admitted-run-context.js");

await ensureMcpLoopbackServer();
const runtime = getActiveMcpLoopbackRuntime();
if (!runtime) {
  throw new Error("MCP loopback runtime did not start");
}
const failures: string[] = [];
function check(label: string, ok: boolean, detail: string): void {
  console.log(`  ${ok ? "PASS" : "FAIL"}  ${label} — ${detail}`);
  if (!ok) {
    failures.push(label);
  }
}
const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));
const readMarks = () =>
  Object.fromEntries(
    (fs.existsSync(marks) ? fs.readFileSync(marks, "utf8") : "")
      .split("\n")
      .filter(Boolean)
      .map((line) => {
        const [name, at] = line.split(" ");
        return [name, Number(at)];
      }),
  ) as Record<string, number>;

const admission = admissionApi.prepareAgentRunAdmission({
  cfg: cfg as never,
  facts: {
    runId: "proof-shutdown",
    agentId: "main",
    ingress: { kind: "system", boundary: "proof-197119", state: "present" },
  },
  operationalRunInstance: admissionApi.createOperationalRunInstanceRef("proof-shutdown"),
});
const grant = store.mintMcpLoopbackClientGrant({
  context: { sessionKey: "agent:main:main", senderIsOwner: true, runId: "proof-shutdown" },
  runtimeOwnerToken: runtime.ownerToken,
  admittedRunContext: await admission.admit("gateway", "gateway-proof-shutdown"),
  toolPolicyConfig: cfg as never,
});
if (
  !store.activateMcpLoopbackClientGrantCapture({
    token: grant.token,
    runtimeOwnerToken: runtime.ownerToken,
    captureKey: "proof-capture",
  })
) {
  throw new Error("capture activation refused");
}
const rpc = async (method: string, params?: unknown) => {
  const response = await fetch(`http://127.0.0.1:${runtime.port}/mcp`, {
    method: "POST",
    headers: {
      authorization: `Bearer ${grant.token}`,
      "content-type": "application/json",
      "x-openclaw-cli-capture-key": "proof-capture",
    },
    body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, ...(params ? { params } : {}) }),
  });
  return { status: response.status, text: await response.text() };
};

let exitCode = 0;
try {
  const list = await rpc("tools/list");
  const names: string[] = (JSON.parse(list.text).result?.tools ?? []).map(
    (tool: { name: string }) => tool.name,
  );
  check(
    "fixture plugin tools are served by the real listener",
    names.includes("shutdown_probe_wait") && names.includes("shutdown_probe_quick"),
    `${names.length} tools listed`,
  );

  console.log("Scenario 1: a call that finishes before shutdown");
  const quick = await rpc("tools/call", { name: "shutdown_probe_quick", arguments: {} });
  check(
    "completes normally",
    quick.status === 200 && quick.text.includes("quick-ok"),
    `HTTP ${quick.status}: ${quick.text.slice(0, 100)}`,
  );

  console.log("Scenario 2: shutdown begins while a callback is still executing");
  const inFlight = rpc("tools/call", { name: "shutdown_probe_wait", arguments: {} }).then(
    (result) => ({ settled: "response" as const, ...result, at: Date.now() }),
    (error: unknown) => ({ settled: "error" as const, status: 0, text: String(error), at: Date.now() }),
  );
  for (let waited = 0; waited < 15_000 && !readMarks()["callback-started"]; waited += 25) {
    await sleep(25);
  }
  const started = readMarks()["callback-started"];
  check("callback is executing", Boolean(started), started ? "callback-started recorded" : "never started");
  await sleep(300);
  check(
    "it is still running 300 ms later (nothing ends it on its own)",
    !readMarks()["callback-signal-aborted"],
    "no abort recorded yet",
  );

  const closeStartedAt = Date.now();
  const closeOutcome = await Promise.race([
    closeMcpLoopbackServer().then(() => "closed" as const),
    sleep(10_000).then(() => "still-open-after-10s" as const),
  ]);
  const closeResolvedAt = Date.now();
  const after = readMarks();
  check(
    "close() resolves instead of waiting on the open response",
    closeOutcome === "closed",
    `${closeOutcome} after ${closeResolvedAt - closeStartedAt} ms`,
  );
  check(
    "the callback's execute signal aborted when shutdown began",
    Boolean(after["callback-signal-aborted"]) &&
      after["callback-signal-aborted"] - closeStartedAt < 1_000,
    after["callback-signal-aborted"]
      ? `${after["callback-signal-aborted"] - closeStartedAt} ms after close() was called`
      : "signal never aborted",
  );
  check(
    "the callback's cleanup completed before close() resolved",
    Boolean(after["callback-cleanup-done"]) && after["callback-cleanup-done"] <= closeResolvedAt,
    after["callback-cleanup-done"]
      ? `cleanup done ${closeResolvedAt - after["callback-cleanup-done"]} ms before close() resolved`
      : "cleanup never finished",
  );
  const settled = await Promise.race([inFlight, sleep(3_000).then(() => undefined)]);
  check(
    "the client's request is released",
    settled !== undefined,
    settled ? `${settled.settled}: HTTP ${settled.status} ${settled.text.slice(0, 90)}` : "still pending 3 s after close",
  );
} finally {
  admission.close();
  await Promise.race([closeMcpLoopbackServer(), sleep(2_000)]);
  fs.rmSync(dir, { recursive: true, force: true });
}
if (failures.length > 0) {
  console.error(`\n${failures.length} runtime assertion(s) FAILED: ${failures.join("; ")}`);
  exitCode = 1;
} else {
  console.log("\nAll runtime assertions passed.");
}
process.exit(exitCode);
```

</details>

### Tests

No test changes. Built-Gateway proof with a real MCP client, SIGTERM and SIGUSR2 restart: https://github.com/openclaw/openclaw/pull/197119#issuecomment-6860143982

### Proof limits

- The plugin tool is a fixture written for the proof; no third-party plugin was exercised.
- The "before" run isolates the P2 fix (the combined signal). It is not a run on `main`, so it does not separately show the effect of the earlier `work.beginClose()` change.
- The proof runs the listener in a standalone process, not inside a full Gateway.

*Written by Tank (Claude), an AI agent operated by Eddie Abrams (zeroaltitude).*

